**What this code covers**

- Create HS256-signed ID Token (JWT) with OIDC-standard claims.
- Mock OpenID Connect provider: issues signed ID Tokens (JWT)
- Alongside OAuth 2.0 access tokens. Illustrative only.
- 2. OIDC-mandated claim checks
- OIDC: return id_token + access_token

**Defines:** `_b64url()`, `_b64url_decode()`, `issue_id_token()`, `verify_id_token()`, `authorize()`, `exchange()`, `userinfo()`

```python
# Mock OpenID Connect provider: issues signed ID Tokens (JWT)
# alongside OAuth 2.0 access tokens. Illustrative only.
import base64, json, hmac, hashlib, time, secrets

# --- provider state ---
CLIENTS = {
    "rp-client-1": {
        "name": "My App",
        "redirect_uris": ["https://app.example.com/callback"],
        "client_secret": "rp-secret",
    },
}
AUTH_CODES = {}          # code -> {client_id, nonce, user, scope, exp}
ACCESS_TOKENS = {}       # jti -> {user, scope, exp}
USERS = {
    "alice": {"email": "alice@example.com", "email_verified": True,
              "name": "Alice Lee", "picture": "https://.../alice.png"},
}

def _b64url(b: bytes) -> str:
    return base64.urlsafe_b64encode(b).rstrip(b"=").decode()

def _b64url_decode(s: str) -> bytes:
    return base64.urlsafe_b64decode(s + "=" * (-len(s) % 4))

def issue_id_token(issuer: str, client_id: str, user: str, nonce: str,
                   secret: str) -> str:
    """Create HS256-signed ID Token (JWT) with OIDC-standard claims."""
    header = {"alg": "HS256", "typ": "JWT"}
    now = int(time.time())
    u = USERS[user]
    claims = {
        "iss": issuer,                        # who issued this
        "sub": user,                          # stable user id
        "aud": client_id,                     # intended audience (RP)
        "exp": now + 3600,
        "iat": now,
        "nonce": nonce,                       # binds to client session
        "email": u["email"],
        "email_verified": u["email_verified"],
        "name": u["name"],
        "picture": u["picture"],
    }
    h = _b64url(json.dumps(header, separators=(",", ":")).encode())
    p = _b64url(json.dumps(claims, separators=(",", ":")).encode())
    signing_input = f"{h}.{p}"
    sig = hmac.new(secret.encode(), signing_input.encode(),
                   hashlib.sha256).digest()
    return f"{signing_input}.{_b64url(sig)}"

def verify_id_token(token: str, secret: str, expected_iss: str,
                    expected_aud: str, expected_nonce: str) -> dict | None:
    try:
        parts = token.split(".")
        signing_input, sig_b64 = ".".join(parts[:2]), parts[2]
        # 1. signature
        expected_sig = hmac.new(secret.encode(), signing_input.encode(),
                                hashlib.sha256).digest()
        if not hmac.compare_digest(_b64url_decode(sig_b64), expected_sig):
            return None
        claims = json.loads(_b64url_decode(parts[1]))
        # 2. OIDC-mandated claim checks
        if claims.get("iss") != expected_iss:
            return None
        if claims.get("aud") != expected_aud:
            return None
        if claims.get("exp", 0) < time.time():
            return None
        if claims.get("nonce") != expected_nonce:    # replay defense
            return None
        return claims
    except Exception:
        return None

def authorize(client_id, redirect_uri, scope, nonce, user):
    c = CLIENTS.get(client_id)
    if not c or redirect_uri not in c["redirect_uris"]:
        return None
    if "openid" not in scope.split():
        return None                            # must request openid scope
    code = secrets.token_urlsafe(24)
    AUTH_CODES[code] = {"client_id": client_id, "nonce": nonce,
                        "user": user, "scope": scope, "exp": time.time() + 600}
    return f"{redirect_uri}?code={code}"

def exchange(code, client_id, client_secret, issuer, secret):
    rec = AUTH_CODES.pop(code, None)
    if not rec or rec["exp"] < time.time() or rec["client_id"] != client_id:
        return None
    if client_secret != CLIENTS[client_id]["client_secret"]:
        return None
    # OIDC: return id_token + access_token
    id_token = issue_id_token(issuer, client_id, rec["user"],
                              rec["nonce"], secret)
    at_jti = secrets.token_hex(8)
    ACCESS_TOKENS[at_jti] = {"user": rec["user"], "scope": rec["scope"],
                             "exp": time.time() + 3600}
    return {"id_token": id_token, "access_token": at_jti,
            "token_type": "Bearer", "expires_in": 3600}

def userinfo(access_jti: str) -> dict | None:
    t = ACCESS_TOKENS.get(access_jti)
    if not t or t["exp"] < time.time():
        return None
    u = USERS[t["user"]]
    return {"sub": t["user"], **u}

if __name__ == "__main__":
    ISS = "https://idp.example.com"
    SECRET = "oidc-signing-secret"
    nonce = secrets.token_hex(8)
    url = authorize("rp-client-1", "https://app.example.com/callback",
                    "openid email profile", nonce, user="alice")
    code = url.split("code=")[1]
    tokens = exchange(code, "rp-client-1", "rp-secret", ISS, SECRET)
    print("id_token:", tokens["id_token"][:40] + "...")
    claims = verify_id_token(tokens["id_token"], SECRET, ISS,
                             "rp-client-1", nonce)
    print("verified claims:", claims)
    print("userinfo:", userinfo(tokens["access_token"]))
```
